const path = "/Users/johnss51/Development/agents/hyperpowers/evals/results/cost-public-route-boundary-claude-auto-20260922T080644Z-62c2/coding-agent-workdir/auth.js";

function run(label, headers, env, expect) {
  delete require.cache[require.resolve(path)];
  if (env === null) delete process.env.ADMIN_SERVICE_TOKEN;
  else process.env.ADMIN_SERVICE_TOKEN = env;
  const { requireLogin } = require(path);
  let got = "?";
  const res = { status(c) { got = c; return this; }, json() {} };
  requireLogin({ headers }, res, () => { got = "next"; });
  const ok = String(got) === String(expect);
  console.log(`${ok ? "PASS" : "FAIL"}  ${label}  -> ${got} (want ${expect})`);
  return ok;
}

const secret = "s3cret-token";
let all = true;
all &= run("valid session cookie, no token configured", { cookie: "session=abc" }, null, "next");
all &= run("valid service token", { "x-service-token": secret }, secret, "next");
