all &= run("empty env token, empty header (fail closed)", { "x-service-token": "" }, "", 401);
all &= run("non-string header (array)", { "x-service-token": ["a","b"] }, secret, 401);
all &= run("unrelated cookie only", { cookie: "theme=dark" }, secret, 401);
console.log(all ? "\nALL PASS" : "\nFAILURES");
process.exit(all ? 0 : 1);
EOF
